/**
 * Encabezado y pie de página de TODOS los PDF de la plataforma: los
 * documentos integrados (preview-page.tsx, captura de la vista previa) y los
 * que compone PDFGenerator (plantillas de Word, firmas, informes).
 *
 * Por qué existe (2026-10-21): cada motor pintaba su propio encabezado y pie,
 * con textos de 6 pt en gris claro («1 / 7», «Generated by Codec Document»)
 * y una marca de agua grande con el logo en el centro de cada hoja. El
 * documento se leía como un borrador generado, no como un contrato. El modelo
 * es el de DocuSign / Dropbox Sign: una cabecera sobria con quién emite el
 * documento y su número, y un pie con el identificador, la huella SHA-256, el
 * marco legal y «Página X de Y», que es lo que un trabajador en EE. UU.
 * reconoce como documento serio.
 */
import type { jsPDF } from 'jspdf';
import type { DocumentBranding } from '../types/document';

export const NAVY: [number, number, number] = [15, 42, 95];
const INDIGO: [number, number, number] = [79, 70, 229];
const GRIS: [number, number, number] = [100, 116, 139];
const GRIS_CLARO: [number, number, number] = [148, 163, 184];
const LINEA: [number, number, number] = [214, 220, 232];

export interface MembreteOpciones {
  pdf: jsPDF;
  pageWidth: number;
  pageHeight: number;
  margin: number;
  page: number;
  totalPages: number;
  language: 'en' | 'es';
  branding?: Partial<DocumentBranding> | null;
  /** Título del documento, para la cabecera. */
  docTitle?: string;
  /** Huella SHA-256 del contenido: de ahí sale el número del documento. */
  documentHash?: string;
  /** «E-SIGN & UETA», «Ley 527 de 1999»… */
  marcoLegal?: string;
  /** Dónde termina la cabecera (la línea fina). El cuerpo empieza debajo. */
  headerBottom: number;
  /** Dónde empieza el pie (la línea fina). El cuerpo termina encima. */
  footerTop: number;
  /** En la primera página con membrete propio (logo grande de la empresa) no
   *  se repite el nombre de la empresa arriba. */
  omitirEmpresaEnCabecera?: boolean;
  /** Pintar el logo en la cabecera (en la primera página con membrete grande
   *  ya está). */
  logoEnCabecera?: boolean;
}

/** «CDX-1A2B3C4D»: número corto y estable del documento, sacado de su huella. */
export function numeroDeDocumento(documentHash?: string): string {
  const base = (documentHash || '').replace(/[^a-f0-9]/gi, '');
  return base.length >= 8 ? `CDX-${base.slice(0, 8).toUpperCase()}` : '';
}

function texto(pdf: jsPDF, t: string, x: number, y: number, opts?: { align?: 'left' | 'center' | 'right' }) {
  try { pdf.text(t, x, y, opts); } catch { /* un carácter raro no debe tumbar el PDF */ }
}

function ancho(pdf: jsPDF, t: string): number {
  try { return pdf.getTextWidth(t); } catch { return t.length * 1.5; }
}

export function pintarCabecera(o: MembreteOpciones): void {
  const { pdf, pageWidth: PW, margin: M, branding, language } = o;
  const es = language === 'es';

  // Filete superior: azul marino con un remate índigo, a todo lo ancho.
  pdf.setFillColor(...NAVY);
  pdf.rect(0, 0, PW, 1.6, 'F');
  pdf.setFillColor(...INDIGO);
  pdf.rect(PW * 0.72, 0, PW * 0.28, 1.6, 'F');

  const centroY = (1.6 + o.headerBottom) / 2 + 1.2;
  let x = M;

  const hasLogo = Boolean(branding?.enableLogo && branding?.logoDataUrl);
  if (hasLogo && o.logoEnCabecera !== false) {
    try {
      const props = pdf.getImageProperties(branding!.logoDataUrl!);
      const maxH = Math.max(4, o.headerBottom - 5.5);
      const maxW = 26;
      const ratio = props.width / Math.max(1, props.height);
      let h = maxH;
      let w = h * ratio;
      if (w > maxW) { w = maxW; h = w / ratio; }
      const fmt = branding!.logoDataUrl!.includes('image/png') ? 'PNG' : 'JPEG';
      pdf.addImage(branding!.logoDataUrl!, fmt, x, centroY - h / 2 - 1.2, w, h, undefined, 'FAST');
      x += w + 3;
    } catch { /* un logo roto no impide generar el documento */ }
  }

  const empresa = (branding?.companyLegalName || '').trim();
  if (empresa && !o.omitirEmpresaEnCabecera) {
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(8.5);
    pdf.setTextColor(...NAVY);
    texto(pdf, empresa.slice(0, 48), x, centroY);
    const lema = (branding?.headerText || '').trim();
    if (lema && lema.toLowerCase() !== empresa.toLowerCase()) {
      pdf.setFont('helvetica', 'normal');
      pdf.setFontSize(6.2);
      pdf.setTextColor(...GRIS);
      texto(pdf, lema.slice(0, 60), x, centroY + 3.2);
    }
  }

  // Derecha: qué documento es y su número.
  const titulo = (o.docTitle || '').trim().toUpperCase();
  const numero = numeroDeDocumento(o.documentHash);
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(6.6);
  pdf.setTextColor(...NAVY);
  if (titulo) {
    let t = titulo;
    const max = PW / 2 - M;
    while (t.length > 8 && ancho(pdf, t) > max) t = `${t.slice(0, -2).trimEnd()}…`;
    texto(pdf, t, PW - M, numero ? centroY - 1.2 : centroY, { align: 'right' });
  }
  if (numero) {
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(6.2);
    pdf.setTextColor(...GRIS);
    texto(pdf, `${es ? 'N.º de documento' : 'Document ID'}: ${numero}`, PW - M, titulo ? centroY + 2.6 : centroY, { align: 'right' });
  }

  pdf.setDrawColor(...LINEA);
  pdf.setLineWidth(0.25);
  pdf.line(M, o.headerBottom, PW - M, o.headerBottom);
}

export function pintarPie(o: MembreteOpciones): void {
  const { pdf, pageWidth: PW, pageHeight: PH, margin: M, branding, language } = o;
  const es = language === 'es';
  const y0 = o.footerTop;

  const propio = (branding?.footerText || '').trim();
  if (propio) {
    pdf.setFont('helvetica', 'italic');
    pdf.setFontSize(6.4);
    pdf.setTextColor(...GRIS);
    texto(pdf, propio.slice(0, 120), PW / 2, y0 - 1.8, { align: 'center' });
  }

  pdf.setDrawColor(...LINEA);
  pdf.setLineWidth(0.25);
  pdf.line(M, y0, PW - M, y0);

  const fila1 = y0 + 3.6;
  const fila2 = y0 + 6.6;

  // Izquierda: número del documento y huella.
  const numero = numeroDeDocumento(o.documentHash);
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(6.4);
  pdf.setTextColor(...NAVY);
  texto(pdf, numero ? `${es ? 'Documento' : 'Document'} ${numero}` : (es ? 'Documento electrónico' : 'Electronic document'), M, fila1);
  if (o.documentHash) {
    pdf.setFont('helvetica', 'normal');
    pdf.setFontSize(5.6);
    pdf.setTextColor(...GRIS_CLARO);
    texto(pdf, `SHA-256 ${o.documentHash.slice(0, 16)}…${o.documentHash.slice(-8)}`, M, fila2);
  }

  // Centro: marco legal y quién lo protege.
  if (o.marcoLegal) {
    pdf.setFont('helvetica', 'bold');
    pdf.setFontSize(6.2);
    pdf.setTextColor(...INDIGO);
    texto(pdf, es ? `Firma electrónica conforme a ${o.marcoLegal}` : `Electronic signature compliant with ${o.marcoLegal}`, PW / 2, fila1, { align: 'center' });
  }
  pdf.setFont('helvetica', 'normal');
  pdf.setFontSize(5.6);
  pdf.setTextColor(...GRIS_CLARO);
  texto(pdf, es ? 'Protegido con Codec Document · codecdocument.com' : 'Secured by Codec Document · codecdocument.com', PW / 2, fila2, { align: 'center' });

  // Derecha: página.
  pdf.setFont('helvetica', 'bold');
  pdf.setFontSize(7);
  pdf.setTextColor(...NAVY);
  texto(pdf, es ? `Página ${o.page} de ${o.totalPages}` : `Page ${o.page} of ${o.totalPages}`, PW - M, fila1, { align: 'right' });

  // Línea fina de cierre, para que el pie no quede flotando.
  void PH;
}

/**
 * Marca de agua con el logo: sólo si la empresa la activó, y casi
 * imperceptible. Antes era el logo a 60 % del ancho y 10 % de opacidad en el
 * centro de cada hoja, lo primero que se veía al abrir el documento.
 */
export function pintarMarcaDeAgua(pdf: jsPDF, branding: Partial<DocumentBranding> | null | undefined, PW: number, PH: number): void {
  if (!branding?.enableLogoWatermark || !branding.logoDataUrl) return;
  try {
    const anyPdf = pdf as unknown as { GState?: new (o: { opacity: number }) => unknown; setGState?: (g: unknown) => void };
    pdf.saveGraphicsState();
    if (typeof anyPdf.GState === 'function' && typeof anyPdf.setGState === 'function') {
      anyPdf.setGState(new anyPdf.GState({ opacity: 0.035 }));
    }
    const props = pdf.getImageProperties(branding.logoDataUrl);
    const ratio = props.width / Math.max(1, props.height);
    let w = PW * 0.34;
    let h = w / ratio;
    if (h > PH * 0.22) { h = PH * 0.22; w = h * ratio; }
    const fmt = branding.logoDataUrl.includes('image/png') ? 'PNG' : 'JPEG';
    pdf.addImage(branding.logoDataUrl, fmt, (PW - w) / 2, (PH - h) / 2, w, h, undefined, 'FAST');
    pdf.restoreGraphicsState();
  } catch { /* decorativa: si falla, el documento sigue */ }
}
